const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.connectOverCDP('ws://localhost:9222/devtools/page/704E3CA6C1D7E38F1378DDB1DC08B771');
  const context = browser.contexts()[0];
  const page = context.pages()[0] || await context.newPage();

  console.log('Current URL:', page.url());
  console.log('Page title:', await page.title());

  await page.waitForLoadState('networkidle');

  // Try to fill in username
  const usernameSelectors = [
    'input[placeholder*="账号"]',
    'input[placeholder*="手机"]',
    'input[placeholder*="用户"]',
    'input[type="text"]',
    'input[name*="user"]',
    'input[name*="phone"]',
    'input[name*="account"]',
    'input[id*="user"]',
    'input[id*="account"]',
  ];

  let usernameFilled = false;
  for (const sel of usernameSelectors) {
    const inp = await page.$(sel);
    if (inp) {
      await inp.fill('18926879306');
      console.log('Username filled via:', sel);
      usernameFilled = true;
      break;
    }
  }

  // Fill password
  const passwordSelectors = [
    'input[type="password"]',
    'input[name*="pwd"]',
    'input[name*="pass"]',
    'input[id*="pwd"]',
    'input[id*="pass"]',
  ];

  for (const sel of passwordSelectors) {
    const inp = await page.$(sel);
    if (inp) {
      await inp.fill('100911yzpYZP');
      console.log('Password filled via:', sel);
      break;
    }
  }

  // Click login button
  const buttonSelectors = [
    'button:has-text("登录")',
    'button:has-text("登陆")',
    'button[type="submit"]',
    'button.primary',
    'button[class*="login"]',
    'button[class*="submit"]',
  ];

  for (const sel of buttonSelectors) {
    const btn = await page.$(sel);
    if (btn) {
      await btn.click();
      console.log('Clicked login button via:', sel);
      break;
    }
  }

  await page.waitForTimeout(3000);
  console.log('URL after login:', page.url());

  await browser.close();
  console.log('Done!');
})();
